local cachedMap, cached
function NS:GetImportedNodeLocations(map)
    if map == cachedMap then return cached end
    local rows = {}
    for _, row in ipairs(packed[map] or {}) do
        rows[#rows+1] = {kind=row[1]==1 and "herb" or "ore", id=row[2],
            x=row[3]/10000, y=row[4]/10000, uncertainty=1}
    end
    cachedMap, cached = map, {version=1,maps={[map]=rows}}
    return cached
end
